static bool covers(const lv_font_t *f,const char *text){
 uint32_t at=0;while(text[at]){uint32_t cp=_lv_txt_encoded_next(text,&at);if(cp<32)continue;lv_font_glyph_dsc_t d={0};if(!f->get_glyph_dsc(f,&d,cp,0)||d.is_placeholder)return false;}return true;
}
typedef struct {unsigned pixels;const lv_font_t *font;} NativeSize;
const lv_font_t *ui_native_font_select(const lv_font_t *source,unsigned zoom,const char *text){
 const NativeSize *sizes=NULL;unsigned count=0,pixels=0;

 static const NativeSize body[]={{26,&ui_native_body_26},{24,&ui_native_body_24},{22,&ui_native_body_22},{20,&ui_native_body_20},{18,&ui_native_body_18},{16,&ui_native_body_16},{14,&ui_native_body_14}};

 if(source==&ui_font_text_14){sizes=body;count=sizeof(body)/sizeof(*body);pixels=28;}

 static const NativeSize title[]={{42,&ui_native_title_42},{40,&ui_native_title_40},{36,&ui_native_title_36},{32,&ui_native_title_32},{28,&ui_font_text_14},{26,&ui_native_body_26},{24,&ui_native_body_24},{22,&ui_native_body_22},{20,&ui_native_body_20},{18,&ui_native_body_18},{16,&ui_native_body_16},{14,&ui_native_body_14}};

 if(source==&ui_font_portal_title_22){sizes=title;count=sizeof(title)/sizeof(*title);pixels=44;}

 static const NativeSize number24[]={{44,&ui_native_number_44},{40,&ui_native_number_40},{36,&ui_native_number_36},{32,&ui_native_number_32},{28,&ui_font_text_14},{26,&ui_native_body_26},{24,&ui_native_body_24},{22,&ui_native_body_22},{20,&ui_native_body_20},{18,&ui_native_body_18},{16,&ui_native_body_16},{14,&ui_native_body_14}};

 if(source==&ui_font_text_24){sizes=number24;count=sizeof(number24)/sizeof(*number24);pixels=48;}

 static const NativeSize number28[]={{52,&ui_native_number_52},{48,&ui_native_number_48},{44,&ui_native_number_44},{40,&ui_native_number_40},{36,&ui_native_number_36},{32,&ui_native_number_32},{28,&ui_font_text_14},{26,&ui_native_body_26},{24,&ui_native_body_24},{22,&ui_native_body_22},{20,&ui_native_body_20},{18,&ui_native_body_18},{16,&ui_native_body_16},{14,&ui_native_body_14}};

 if(source==&ui_font_text_28){sizes=number28;count=sizeof(number28)/sizeof(*number28);pixels=56;}

 if(!sizes)return NULL;unsigned wanted=pixels*zoom/256;for(unsigned i=0;i<count;++i)if(sizes[i].pixels<=wanted&&covers(sizes[i].font,text))return sizes[i].font;return NULL;
}
